const body = $('Schedule event webhook').item.json.body;
const calResponse = $input.first().json;
const events = calResponse.items || calResponse.data?.items || [];

if (events.length === 0) {
  return [{ json: { conflict: false } }];
}

// Auto-suggested slots: naive half-hour-increment search starting right after the requested slot,
// up to 6 tries (3 hours out) - a real 'availability rules' engine (working hours, per-rep
// calendars, buffer time) isn't specified anywhere in the source docs, so this is a deliberately
// simple placeholder algorithm, flagged as such rather than presented as the real thing.
const durationMs = body.durationMinutes * 60000;
const suggestions = [];
let candidate = new Date(new Date(body.scheduledAt).getTime() + durationMs);
for (let i = 0; i < 6 && suggestions.length < 3; i++) {
  suggestions.push(candidate.toISOString());
  candidate = new Date(candidate.getTime() + 30 * 60000);
}

return [{
  json: {
    conflict: true,
    conflictingEventCount: events.length,
    suggestedSlots: suggestions,
  },
}];
